const tabId = 118779795;
const searchTrending = await browserjs(tabId, async () => {
  const pagesToSearch = ['/today', '/community', '/puzzles', '/daily', '/forum/category/more-puzzles', '/news', '/articles', '/forum'];
  const hits = {};
  for (const page of pagesToSearch) {
    try {
      const res = await fetch(page);
      const text = await res.text();
      const hasTrending = text.toLowerCase().includes('trending');
      const parser = new DOMParser();
      const doc = parser.parseFromString(text, 'text/html');
      const trendingMatches = [];
      const walker = doc.createTreeWalker(doc.body, NodeFilter.SHOW_TEXT);
      let node;
      while (node = walker.nextNode()) {
        if (node.textContent.toLowerCase().includes('trending')) {
          trendingMatches.push({
            text: node.textContent.trim(),
            parentTag: node.parentElement?.tagName,
            parentClass: node.parentElement?.className,
            context: node.parentElement?.parentElement?.textContent?.trim().slice(0, 150)
          });
        }
      }
      hits[page] = { hasTrending, matches: trendingMatches };
    } catch (e) {
      hits[page] = { error: e.message };
    }
  }
  return hits;
});
console.log(JSON.stringify(searchTrending, null, 2));

