const tabId = 118779795;
const scriptAnalysis = await browserjs(tabId, async () => {
  // Check if any script contains "trending"
  const scripts = Array.from(document.querySelectorAll('script[src]')).map(s => s.src);
  const found = [];
  for (const src of scripts.slice(0, 15)) {
    try {
      const res = await fetch(src);
      const text = await res.text();
      const idx = text.toLowerCase().indexOf('trending');
      if (idx !== -1) {
        found.push({ src, snippet: text.slice(Math.max(0, idx - 50), idx + 100) });
      }
    } catch (e) {}
  }
  return found;
});
console.log(scriptAnalysis);

