const tabId = 118779795;
const sitemapCheck = await browserjs(tabId, async () => {
  const indexRes = await fetch('/sitemapindex.xml');
  const indexText = await indexRes.text();
  const sitemaps = (indexText.match(/<loc>[^<]+<\/loc>/g) || []).map(m => m.replace(/<\/?loc>/g, ''));

  const matches = [];
  for (const sm of sitemaps.slice(0, 15)) {
    try {
      const res = await fetch(sm);
      const text = await res.text();
      const locs = (text.match(/<loc>[^<]+<\/loc>/g) || []).map(m => m.replace(/<\/?loc>/g, ''));
      const trendLocs = locs.filter(l => l.includes('trend') || l.includes('puzzle'));
      if (trendLocs.length > 0) {
        matches.push({ sitemap: sm, trendLocs: trendLocs.slice(0, 10), count: trendLocs.length });
      }
    } catch (e) {}
  }
  return matches;
});
console.log(JSON.stringify(sitemapCheck, null, 2));

