const tabId = 118779795;
const searchAllScripts = await browserjs(tabId, async () => {
  const scripts = Array.from(document.querySelectorAll('script[src]')).map(s => s.src);
  const hits = [];
  for (const src of scripts) {
    if (!src.includes('chess.com') && !src.startsWith('/')) continue;
    try {
      const res = await fetch(src);
      const text = await res.text();
      const matches = [...text.matchAll(/trending[a-zA-Z0-9_\-\/]*/gi)];
      if (matches.length > 0) {
        hits.push({ src, matches: matches.map(m => m[0]).slice(0, 10) });
      }
    } catch (e) {}
  }
  return hits;
});
console.log(JSON.stringify(searchAllScripts, null, 2));

